// Checks Your settings and works out what started this run: a new request, the approval page, an
// approve or cancel button, a customer's reply, or the 10 minute check for texts that are due.
const s = $('Your settings').first().json;
const phone = v => {
  const raw = String(v || '').trim();
  const digits = raw.replace(/\D/g, '');
  if (!digits) return '';
  if (raw.startsWith('+') && digits.length >= 8 && digits.length <= 15) return '+' + digits;
  if (digits.length === 10) return '+1' + digits;
  if (digits.length === 11 && digits.startsWith('1')) return '+' + digits;
  return '';
};
const inWindow = (t, start, end) => {
  const [sh, sm] = start.split(':').map(Number), [eh, em] = end.split(':').map(Number);
  const m = t.hour * 60 + t.minute, a = sh * 60 + sm, b = eh * 60 + em;
  return a === b ? false : a < b ? (m >= a && m < b) : (m >= a || m < b);
};
const fill = (tpl, vals) => String(tpl).replace(/\{(\w+)\}/g, (m, k) => (k in vals ? vals[k] : m));
const esc = v => String(v === undefined || v === null ? '' : v).replace(/[&<>"']/g, ch => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[ch]));
const firstName = n => String(n || '').trim().split(/\s+/)[0] || 'there';
const ran = name => { try { return $(name).isExecuted; } catch (e) { return false; } };
const num = (v, d) => (v === '' || v === null || v === undefined || isNaN(Number(v))) ? d : Number(v);
const bool = (v, d) => (v === undefined || v === null || v === '') ? d : !['false', 'no', 'off', '0'].includes(String(v).trim().toLowerCase());
const hhmm = (v, d) => /^([01]?\d|2[0-3]):[0-5]\d$/.test(String(v || '').trim()) ? String(v).trim().padStart(5, '0') : d;

const business_number = phone(s.business_number);
const owner_cell = phone(s.owner_cell);
if (!business_number || !owner_cell) {
  throw new Error('Your settings: business_number and owner_cell must both be phone numbers, like +15551234567.');
}
if (['+15555550100', '+15555550199'].includes(business_number) || ['+15555550100', '+15555550199'].includes(owner_cell)) {
  throw new Error('Your settings: replace the example phone numbers with your Twilio number and your cell before you publish this.');
}
const timezone = String(s.timezone || 'America/New_York').trim();
if (!DateTime.now().setZone(timezone).isValid) {
  throw new Error('Your settings: "' + timezone + '" is not a time zone n8n knows. Use a name like America/New_York.');
}
const n8n_url = String(s.n8n_url || '').trim().replace(/\/+$/, '');
if (!/^https?:\/\/\S+$/.test(n8n_url) || /your-instance/.test(n8n_url)) {
  throw new Error('Your settings: n8n_url must be the address of your n8n, like https://yourname.app.n8n.cloud. The approval links use it.');
}
const request_key = String(s.request_key || '').trim();
if (request_key.length < 12 || /change-me/i.test(request_key)) {
  throw new Error('Your settings: request_key must be a long random phrase of your own (12 characters or more). Anything that sends requests must include it.');
}
const gaps = String(s.followup_days === undefined ? '2, 5' : s.followup_days).split(',').map(x => Number(x.trim())).filter(x => x > 0 && x <= 60);
const followups = [s.followup_1, s.followup_2, s.followup_3].map(x => String(x || '').trim());
const DEFAULT_FOLLOWUP = [
  'Hi {first_name}, {business_name} again, following up on our text from {sent_day}. If you would like a hand, just reply here.',
  'Last check-in from {business_name}, {first_name}. If you need anything, reply here any time.',
  'Hi {first_name}, one more note from {business_name}. Reply here if we can help.',
];
const steps = gaps.map((g, i) => ({ after_days: g, text: followups[i] || DEFAULT_FOLLOWUP[Math.min(i, 2)] }));

const cfg = {
  business_name: String(s.business_name || 'your business').trim(),
  business_number, owner_cell, timezone, n8n_url, request_key,
  require_consent: bool(s.require_consent, true),
  cooldown_days: Math.max(0, num(s.cooldown_days, 30)),
  steps,
  optout_line: String(s.optout_line === undefined ? 'Reply STOP to opt out.' : s.optout_line).trim(),
  customer_hours_start: hhmm(s.customer_hours_start, '09:00'),
  customer_hours_end: hhmm(s.customer_hours_end, '20:00'),
  quiet_start: hhmm(s.quiet_start, '21:00'),
  quiet_end: hhmm(s.quiet_end, '07:00'),
  approval_hours: Math.max(1, num(s.approval_hours, 48)),
  max_per_run: Math.max(1, Math.min(200, num(s.max_per_run, 40))),
  send_email: bool(s.send_email, false),
  email_subject: String(s.email_subject || 'A quick note from {business_name}').trim(),
};

let mode = 'tick', input = {};
if (ran('New outreach request')) { mode = 'request'; input = $('New outreach request').first().json; }
else if (ran('Approval page opened')) { mode = 'page'; input = $('Approval page opened').first().json; }
else if (ran('Approve or cancel')) { mode = 'decide'; input = $('Approve or cancel').first().json; }
else if (ran('Customer replied')) { mode = 'reply'; input = $('Customer replied').first().json; }

return [{ json: { mode, cfg, input } }];

// A new request: something happened (a storm, a recall, an outage) and here are the customers it
// touches, with the message to send them. Nothing goes to customers yet. It works out who can be texted,
// keeps the request, and queues a text to you with a link to review and approve it.
