  const m = t.hour * 60 + t.minute, a = sh * 60 + sm, b = eh * 60 + em;
  return a === b ? false : a < b ? (m >= a && m < b) : (m >= a || m < b);
};
const fill = (tpl, vals) => String(tpl).replace(/\{(\w+)\}/g, (m, k) => (k in vals ? vals[k] : m));
const esc = v => String(v === undefined || v === null ? '' : v).replace(/[&<>"']/g, ch => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[ch]));
const firstName = n => String(n || '').trim().split(/\s+/)[0] || 'there';
const st = $getWorkflowStaticData('global');
st.req = st.req || {}; st.cad = st.cad || {}; st.contacted = st.contacted || {}; st.optout = st.optout || {}; st.owner = st.owner || [];
const now = DateTime.now().setZone(cfg.timezone);
const b = input.body || {};
const answer = (code, obj) => [{ json: { status_code: code, answer: obj } }];

if (String(b.key || '') !== cfg.request_key) return answer(403, { ok: false, error: 'The key does not match request_key.' });
const title = String(b.title || '').trim().slice(0, 120);
const message = String(b.message || '').trim();
const list = Array.isArray(b.customers) ? b.customers : [];
if (!title || !message) return answer(400, { ok: false, error: 'A request needs a title and a message.' });
if (message.length > 640) return answer(400, { ok: false, error: 'The message is over 640 characters. Keep it to a few sentences.' });
if (!list.length || list.length > 1000) return answer(400, { ok: false, error: 'A request needs between 1 and 1000 customers.' });

const activeFor = {};
Object.values(st.cad).forEach(c => { if (c.status === 'active') activeFor[c.phone] = true; });
const cooldownFrom = now.minus({ days: cfg.cooldown_days }).toISO();
const skipped = { no_phone: 0, not_ok_to_text: 0, opted_out: 0, contacted_recently: 0, already_in_touch: 0, listed_twice: 0 };
const eligible = [];
const seen = {};
for (const c of list) {
  const p = phone(c.phone);
  const okToText = c.ok_to_text === true || ['yes', 'true', 'y', '1'].includes(String(c.ok_to_text || '').trim().toLowerCase());
  if (!p) { skipped.no_phone++; continue; }
  if (seen[p]) { skipped.listed_twice++; continue; }
  seen[p] = true;
  if (cfg.require_consent && !okToText) { skipped.not_ok_to_text++; continue; }
  if (st.optout[p]) { skipped.opted_out++; continue; }
  if (activeFor[p]) { skipped.already_in_touch++; continue; }
  if (cfg.cooldown_days && st.contacted[p] && st.contacted[p] > cooldownFrom) { skipped.contacted_recently++; continue; }
  const name = String(c.name || '').trim() || p;
  eligible.push({ name, first: firstName(name), phone: p, email: /^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(String(c.email || '').trim()) ? String(c.email).trim() : '', detail: String(c.detail || '').slice(0, 80) });
}

const rand = n => Array.from({ length: n }, () => 'abcdefghijkmnpqrstuvwxyz23456789'[Math.floor(Math.random() * 32)]).join('');
const id = rand(8);
const code = rand(24);
st.req[id] = {
  id, code, title, message,
  summary: String(b.summary || '').trim().slice(0, 1500),
  source: String(b.source || '').trim().slice(0, 40),
  created: now.toISO(), status: eligible.length ? 'waiting' : 'empty',
  eligible, skipped, wrapped: false,
};
// Keep the memory small: forget finished requests after 60 days.
const old = now.minus({ days: 60 }).toISO();
Object.values(st.req).forEach(r => { if (r.created < old && r.status !== 'approved') delete st.req[r.id]; });

const skipText = Object.entries(skipped).filter(([, n]) => n).map(([k, n]) => n + ' ' + k.replace(/_/g, ' ')).join(', ');
const link = cfg.n8n_url + '/webhook/outreach-approve?r=' + id + '&c=' + code;
const summary = st.req[id].summary ? st.req[id].summary.slice(0, 700) + '\n\n' : '';
const body = eligible.length
  ? title + '\n' + summary + 'Ready to text ' + eligible.length + ' of them' + (skipText ? ' (skipped: ' + skipText + ')' : '') + '. Nothing goes out until you approve:\n' + link
  : title + '\n' + summary + 'None of them can be texted (' + skipText + '), so there is nothing to approve.';
st.owner.push({ id: 'o' + rand(6), body, tries: 0 });

return answer(200, { ok: true, id, eligible: eligible.length, skipped });

