const now = DateTime.now().setZone(cfg.timezone);
const q = mode === 'decide' ? (input.body || {}) : (input.query || {});
const r = st.req[String(q.r || '')];
const valid = r && String(q.c || '') === r.code;
let notice = '';

const expired = x => x.status === 'waiting' && DateTime.fromISO(x.created) < now.minus({ hours: cfg.approval_hours });
if (valid && expired(r)) r.status = 'expired';

// Nearest time customers may be texted, from now.
const nextSendTime = t => {
  let x = t;
  for (let i = 0; i < 96 && !inWindow(x, cfg.customer_hours_start, cfg.customer_hours_end); i++) x = x.plus({ minutes: 15 });
  return x;
};

if (valid && mode === 'decide') {
  const a = String(q.a || '');
  if (a === 'approve' && r.status === 'waiting') {
    const activeFor = {};
    Object.values(st.cad).forEach(c => { if (c.status === 'active') activeFor[c.phone] = true; });
    let added = 0, dropped = 0;
    const first = nextSendTime(now).toISO();
    for (const e of r.eligible) {
      if (st.optout[e.phone] || activeFor[e.phone]) { dropped++; continue; }
      st.cad[r.id + '|' + e.phone] = { req: r.id, name: e.name, first: e.first, phone: e.phone, email: e.email, detail: e.detail, step: 0, next: first, status: 'active', tries: 0, sent: [], reply: '' };
