    Object.values(st.cad).forEach(c => { if (c.req === r.id && c.status === 'active') { c.status = 'stopped by you'; n++; } });
    notice = 'Stopped. ' + n + ' customer' + (n === 1 ? '' : 's') + ' will not get any more texts about this.';
  } else {
