  }
}

const css = 'body{font-family:-apple-system,Segoe UI,Roboto,sans-serif;max-width:640px;margin:0 auto;padding:16px;color:#1d1d1f;background:#fafafa}h1{font-size:20px}pre{white-space:pre-wrap;background:#fff;border:1px solid #ddd;padding:12px;border-radius:8px;font-family:inherit}table{border-collapse:collapse;width:100%;font-size:14px}td{border-bottom:1px solid #e5e5e5;padding:6px 4px}.n{background:#e8f4ea;border-radius:8px;padding:12px}button{font-size:16px;padding:12px 18px;border-radius:8px;border:0;margin:6px 8px 6px 0}.go{background:#1a7f37;color:#fff}.no{background:#e5e5e5}';
const page = inner => '<!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Outreach</title><style>' + css + '</style></head><body>' + inner + '</body></html>';
const form = (a, label, cls) => '<form method="post" action="' + esc(cfg.n8n_url) + '/webhook/outreach-approve" style="display:inline"><input type="hidden" name="r" value="' + esc(r.id) + '"><input type="hidden" name="c" value="' + esc(r.code) + '"><input type="hidden" name="a" value="' + a + '"><button class="' + cls + '">' + label + '</button></form>';

let html;
if (!valid) {
  html = page('<h1>This link does not work</h1><p>It may be mistyped or from an old request that has been cleared.</p>');
} else {
  const sample = r.eligible[0];
  const preview = sample ? fill(r.message, { first_name: sample.first, business_name: cfg.business_name, detail: sample.detail }) + (cfg.optout_line && !/\bSTOP\b/.test(r.message) ? ' ' + cfg.optout_line : '') : '';
  const skipText = Object.entries(r.skipped || {}).filter(([, n]) => n).map(([k, n]) => n + ' ' + k.replace(/_/g, ' ')).join(', ');
  const cads = Object.values(st.cad).filter(c => c.req === r.id);
  const rows = (r.status === 'approved' ? cads : r.eligible).map(c => '<tr><td>' + esc(c.name) + '</td><td>' + esc(c.detail || '') + '</td><td>' + esc(r.status === 'approved' ? c.status + (c.sent.length ? ', ' + c.sent.length + ' sent' : '') + (c.reply ? ': "' + c.reply.slice(0, 60) + '"' : '') : c.phone) + '</td></tr>').join('');
  let actions = '';
  if (r.status === 'waiting') actions = '<p>' + form('approve', 'Approve and send to ' + r.eligible.length, 'go') + form('cancel', 'Cancel', 'no') + '</p>';
  if (r.status === 'approved' && cads.some(c => c.status === 'active')) actions = '<p>' + form('stop', 'Stop all follow-ups', 'no') + '</p>';
  const counts = r.status === 'approved' ? '<p>' + ['active', 'replied', 'done', 'stopped', 'stopped by you', 'failed'].map(s => [s, cads.filter(c => c.status === s).length]).filter(([, n]) => n).map(([s, n]) => n + ' ' + s).join(', ') + '</p>' : '';
