  html = page(
    (notice ? '<p class="n">' + esc(notice) + '</p>' : '') +
    '<h1>' + esc(r.title) + '</h1>' +
    '<p>Status: <b>' + esc(r.status) + '</b></p>' + counts +
    (r.summary ? '<pre>' + esc(r.summary) + '</pre>' : '') +
    (preview ? '<h2>The first text, as ' + esc(sample.first) + ' would see it</h2><pre>' + esc(preview) + '</pre>' + steps : '') +
    '<p>Texts go out between ' + esc(cfg.customer_hours_start) + ' and ' + esc(cfg.customer_hours_end) + ' (' + esc(cfg.timezone) + ').' + (skipText ? ' Left out: ' + esc(skipText) + '.' : '') + '</p>' +
    actions +
    '<table>' + rows + '</table>'
  );
}
