// A text came in from a customer (Twilio posts it here). STOP and the other opt-out words end every
// follow-up for that number and keep it off future requests. Any other reply ends their follow-ups and
// is passed to you, because a reply is a person who wants to talk.
const { cfg, input } = $('Read your settings').first().json;
const phone = v => {
  const raw = String(v || '').trim();
  const digits = raw.replace(/\D/g, '');
