st.req = st.req || {}; st.cad = st.cad || {}; st.contacted = st.contacted || {}; st.optout = st.optout || {}; st.owner = st.owner || [];
const now = DateTime.now().setZone(cfg.timezone);
const b = input.body || {};
const from = phone(b.From);
const text = String(b.Body || '').trim();
const word = text.toUpperCase().replace(/[^A-Z]/g, '');
const STOP = ['STOP', 'STOPALL', 'UNSUBSCRIBE', 'CANCEL', 'END', 'QUIT', 'OPTOUT', 'REVOKE'];
const START = ['START', 'UNSTOP'];
const rand = n => Array.from({ length: n }, () => 'abcdefghijkmnpqrstuvwxyz23456789'[Math.floor(Math.random() * 32)]).join('');
let outcome = 'ignored';

if (from) {
  const recent = now.minus({ days: 14 }).toISO();
  const mine = Object.values(st.cad).filter(c => c.phone === from && (c.status === 'active' || ((c.status === 'done' || c.status === 'replied') && (c.last || '') > recent)));
  if (STOP.includes(word)) {
    st.optout[from] = now.toISO();
    mine.forEach(c => { if (c.status === 'active') c.status = 'stopped'; });
    outcome = 'opted out';
  } else if (START.includes(word)) {
    delete st.optout[from];
    outcome = 'opted back in';
  } else if (word === 'HELP' || word === 'INFO') {
    outcome = 'help';
  } else if (mine.length) {
    mine.forEach(c => { if (c.status === 'active' || c.status === 'done') c.status = 'replied'; c.reply = text.slice(0, 300); });
    const c = mine[0];
    const r = st.req[c.req] || {};
    st.owner.push({ id: 'o' + rand(6), tries: 0, body: c.name + ' replied about "' + (r.title || 'your outreach') + '":\n"' + text.slice(0, 500) + '"\nCall or text them back: ' + from });
    outcome = 'passed to you';
  }
}
return [{ json: { outcome, twiml: '<?xml version="1.0" encoding="UTF-8"?><Response></Response>' } }];

