const now = DateTime.now().setZone(cfg.timezone);
const texts = [], emails = [];
const rand = n => Array.from({ length: n }, () => 'abcdefghijkmnpqrstuvwxyz23456789'[Math.floor(Math.random() * 32)]).join('');

if (mode === 'tick') {
  // Requests nobody approved in time are closed.
  Object.values(st.req).forEach(r => {
    if (r.status === 'waiting' && DateTime.fromISO(r.created) < now.minus({ hours: cfg.approval_hours })) r.status = 'expired';
  });

  // Customer texts that are due.
  if (inWindow(now, cfg.customer_hours_start, cfg.customer_hours_end)) {
    const due = Object.entries(st.cad).filter(([, c]) => c.status === 'active' && c.next <= now.toISO()).sort((a, b) => (a[1].next < b[1].next ? -1 : 1));
    for (const [key, c] of due) {
      if (texts.length >= cfg.max_per_run) break;
      if (st.optout[c.phone]) { c.status = 'stopped'; continue; }
      const r = st.req[c.req];
      if (!r || r.status !== 'approved') { c.status = 'stopped by you'; continue; }
      const vals = { first_name: c.first, business_name: cfg.business_name, detail: c.detail, sent_day: c.sent[0] ? (DateTime.fromISO(c.sent[0]).setZone(cfg.timezone).hasSame(now, 'day') ? 'earlier today' : DateTime.fromISO(c.sent[0]).setZone(cfg.timezone).toFormat('cccc')) : '' };
      let body;
      if (c.step === 0) {
        body = fill(r.message, vals);
        if (cfg.optout_line && !/\bSTOP\b/.test(body)) body += ' ' + cfg.optout_line;
      } else {
        const step = cfg.steps[c.step - 1];
        if (!step) { c.status = 'done'; continue; }
        body = fill(step.text, vals);
      }
      texts.push({ kind: 'customer', key, to: c.phone, from: cfg.business_number, body });
      if (cfg.send_email && c.email) emails.push({ key, to: c.email, subject: fill(cfg.email_subject, vals), body });
    }
  }

  // One wrap-up per approved request once nobody in it is still active.
  for (const r of Object.values(st.req)) {
    if (r.status !== 'approved' || r.wrapped) continue;
    const cads = Object.values(st.cad).filter(c => c.req === r.id);
    if (!cads.length || cads.some(c => c.status === 'active')) continue;
    const n = s => cads.filter(c => c.status === s).length;
    const parts = [['replied', n('replied')], ['no answer after every follow-up', n('done')], ['opted out', n('stopped')], ['stopped by you', n('stopped by you')], ['could not be texted', n('failed')]].filter(([, x]) => x).map(([s, x]) => x + ' ' + s);
    st.owner.push({ id: 'o' + rand(6), tries: 0, body: 'Finished: "' + r.title + '". ' + cads.length + ' texted: ' + parts.join(', ') + '. Details: ' + cfg.n8n_url + '/webhook/outreach-approve?r=' + r.id + '&c=' + r.code });
    r.wrapped = true;
  }
}

// Your texts go out unless it is your quiet time. Several waiting texts go as one.
st.owner = st.owner.filter(o => (o.tries || 0) < 5);
if (st.owner.length && !inWindow(now, cfg.quiet_start, cfg.quiet_end)) {
  const body = st.owner.map(o => o.body).join('\n\n---\n\n');
  texts.unshift({ kind: 'owner', ids: st.owner.map(o => o.id), to: cfg.owner_cell, from: cfg.business_number, body: body.length > 1550 ? body.slice(0, 1530) + '\n(cut short)' : body });
}
return [{ json: { texts, emails } }];

// Records what Twilio said about each text. A customer text Twilio took moves that customer to the
// next step, or finishes them after the last follow-up. Error 21610 means the number opted out with
// the carrier, so it is treated like STOP. Other refusals are tried again up to three times.
const { cfg } = $('Read your settings').first().json;
const phone = v => {
  const raw = String(v || '').trim();
  const digits = raw.replace(/\D/g, '');
  if (!digits) return '';
  if (raw.startsWith('+') && digits.length >= 8 && digits.length <= 15) return '+' + digits;
  if (digits.length === 10) return '+1' + digits;
  if (digits.length === 11 && digits.startsWith('1')) return '+' + digits;
  return '';
};
const inWindow = (t, start, end) => {
  const [sh, sm] = start.split(':').map(Number), [eh, em] = end.split(':').map(Number);
  const m = t.hour * 60 + t.minute, a = sh * 60 + sm, b = eh * 60 + em;
  return a === b ? false : a < b ? (m >= a && m < b) : (m >= a || m < b);
};
const fill = (tpl, vals) => String(tpl).replace(/\{(\w+)\}/g, (m, k) => (k in vals ? vals[k] : m));
const esc = v => String(v === undefined || v === null ? '' : v).replace(/[&<>"']/g, ch => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[ch]));
const firstName = n => String(n || '').trim().split(/\s+/)[0] || 'there';
const st = $getWorkflowStaticData('global');
st.cad = st.cad || {}; st.contacted = st.contacted || {}; st.optout = st.optout || {}; st.owner = st.owner || [];
const now = DateTime.now().setZone(cfg.timezone);
const sent = $('One item per text').all().map(i => i.json);
const answers = $input.all().map(i => i.json);
const nextSendTime = t => {
  let x = t;
  for (let i = 0; i < 96 && !inWindow(x, cfg.customer_hours_start, cfg.customer_hours_end); i++) x = x.plus({ minutes: 15 });
  return x;
};
let ok = 0, refused = 0;
sent.forEach((t, i) => {
  const a = answers[i] || {};
  const took = !!a.sid;
  took ? ok++ : refused++;
  if (t.kind === 'owner') {
    if (took) st.owner = st.owner.filter(o => !t.ids.includes(o.id));
    else st.owner.forEach(o => { if (t.ids.includes(o.id)) o.tries = (o.tries || 0) + 1; });
    return;
  }
  const c = st.cad[t.key];
  if (!c) return;
  if (took) {
    c.sent.push(now.toISO());
    c.last = now.toISO();
    c.tries = 0;
    st.contacted[c.phone] = now.toISO();
    c.step++;
    const step = cfg.steps[c.step - 1];
    if (!step) c.status = 'done';
    else c.next = nextSendTime(now.plus({ days: step.after_days })).toISO();
  } else if (Number(a.code) === 21610) {
    c.status = 'stopped';
    st.optout[c.phone] = now.toISO();
  } else if ([21211, 21614, 21612].includes(Number(a.code))) {
    c.status = 'failed';
  } else {
    c.tries = (c.tries || 0) + 1;
    if (c.tries >= 3) c.status = 'failed';
  }
});
return [{ json: { sent: ok, refused } }];
